def _hash_files(self, filenames):
    h = hashlib.sha1()
    for fn in filenames:
        with open(fn, 'rb') as f:
            while True:
                block = f.read(131072)
                if not block:
                    break
                h.update(block)
    text = base64.b32encode(h.digest())
